function payMonth(id){const t=monthRows.find(x=>x.id===id);authScreen('پرداخت '+monthLabel(t.month_key),`<p>جلسات موردنظر را انتخاب کنید؛ هر جلسه ${money(tuitionUnit(t))} تومان${Number(t.discount_percent)>0?" با "+money(t.discount_percent)+"٪ تخفیف":""}.</p>${t.paid.map((p,i)=>p?'':`<label class="rules-check"><input type="checkbox" name="slot${i+1}" checked> جلسه ${money(i+1)} · ${AcademyDates.show(t.dates[i])}</label>`).join('')}<label>روش پرداخت<select name="method" id="monthly-method"><option value="card">دیدن شماره کارت</option><option value="bank">واریز به حساب / شبا</option><option value="office">پرداخت در آموزشگاه</option></select></label><div id="monthly-bank"></div>${authInput('reference','کد رهگیری واریز یا شماره رسید آموزشگاه','text','minlength="4" maxlength="64"')}<p class="auth-help">در پرداخت حضوری، شماره رسید را از آموزشگاه بگیرید. ثبت رسید تا تأیید مدیر، جلسه را پرداخت‌شده نمی‌کند.</p>`,'ارسال رسید برای تأیید مدیر',async d=>{const slots=[1,2,3,4].filter(i=>d['slot'+i]);if(!slots.length)throw Error('حداقل یک جلسه انتخاب کنید');if(d.method==='card'&&!bankAccount?.card||d.method==='bank'&&!bankAccount?.iban)throw Error('مشخصات حساب تکمیل نشده؛ با دفتر هماهنگ کنید');await enrollmentAction('submit',{id,slots,method:d.method,reference:digits(d.reference)});modal.close();await reload();goMonthly();toast('رسید برای بررسی مدیر ثبت شد')});const update=()=>{const v=$('monthly-method').value;$('monthly-bank').innerHTML=v==='office'?'<p class="policy">پس از پرداخت در آموزشگاه، شماره رسید دریافت کنید.</p>':`<div class="policy"><b>${esc(bankAccount?.holder||'حساب هنوز تنظیم نشده')}</b><p dir="ltr">${esc(v==='card'?bankAccount?.card||'—':bankAccount?.iban||'—')}</p></div>`};$('monthly-method').onchange=update;update();}
